def bubble_sort(items):
    n = len(items)
    for end in range(n - 1, 0, -1):
        swapped = False
        for index in range(end):
            if items[index] > items[index + 1]:
                items[index], items[index + 1] = items[index + 1], items[index]
                swapped = True
        if not swapped:
            break
    return items

def selection_sort(items):
    for start in range(len(items) - 1):
        min_index = start
        for index in range(start + 1, len(items)):
            if items[index] < items[min_index]:
                min_index = index
        items[start], items[min_index] = items[min_index], items[start]
    return items

def insertion_sort(items):
    for index in range(1, len(items)):
        key = items[index]
        position = index - 1
        while position >= 0 and items[position] > key:
            items[position + 1] = items[position]
            position -= 1
        items[position + 1] = key
    return items

def merge_sort(items):
    if len(items) < 2:
        return items[:]
    middle = len(items) // 2
    left = merge_sort(items[:middle])
    right = merge_sort(items[middle:])
    merged = []
    i = j = 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            merged.append(left[i]); i += 1
        else:
            merged.append(right[j]); j += 1
    return merged + left[i:] + right[j:]

def quick_sort(items):
    if len(items) < 2:
        return items[:]
    pivot = items[len(items) // 2]
    lower = [value for value in items if value < pivot]
    equal = [value for value in items if value == pivot]
    higher = [value for value in items if value > pivot]
    return quick_sort(lower) + equal + quick_sort(higher)

def counting_sort(numbers):
    if not numbers:
        return []
    low, high = min(numbers), max(numbers)
    counts = [0] * (high - low + 1)
    for value in numbers:
        counts[value - low] += 1
    result = []
    for offset, count in enumerate(counts):
        result.extend([offset + low] * count)
    return result
